-- Run against a disposable DB after schema.sql. All sample data rolls back.
-- Assumes auth.users(id) and the normal Supabase roles already exist.
begin;
insert into auth.users(id) values ('11111111-1111-1111-1111-111111111111'), ('22222222-2222-2222-2222-222222222222') on conflict do nothing;
create function pg_temp.rs_assert(value boolean, message text) returns void language plpgsql as $$ begin if value is not true then raise exception 'Assertion: %',message; end if; end; $$;
select pg_temp.rs_assert(not has_function_privilege('anon','public.rs_page(uuid,jsonb)','execute'),'anonymous RPC grant');
select pg_temp.rs_assert(not has_function_privilege('authenticated','public.rs_import(uuid,jsonb)','execute'),'browser RPC grant');
select pg_temp.rs_assert(not has_table_privilege('anon','public.rs_items','select'),'anonymous table grant');
select pg_temp.rs_assert(not has_table_privilege('authenticated','public.rs_items','update'),'browser table grant');
set local role service_role;
select public.rs_import('11111111-1111-1111-1111-111111111111', jsonb_build_object('items',jsonb_agg(jsonb_build_object('videoUrl','https://www.youtube.com/watch?v=test'||n,'readerId','reader'||n,'savedAt',1000+n,'firstSavedAt',1000+n,'updatedAt',1000+n,'title','Title '||n,'author','Ａlice','location','later','tags',jsonb_build_array('A long tag'),'status','saved','checkedAt',1000,'summary','Durable summary','summaryCheckedAt',1000,'description','Original description','notes','Original note')))) from generate_series(1,14) n;
select pg_temp.rs_assert(jsonb_array_length(public.rs_page('11111111-1111-1111-1111-111111111111','{"filter":"watch"}')->'items')=12,'bounded12 page');
select pg_temp.rs_assert((public.rs_page('11111111-1111-1111-1111-111111111111','{"filter":"watch"}')->>'hasNext')::boolean,'keyset has next');
select pg_temp.rs_assert(jsonb_array_length(public.rs_page('11111111-1111-1111-1111-111111111111','{"export":true}')->'items')=4,'full export bounded4');
select pg_temp.rs_assert(not (public.rs_page('11111111-1111-1111-1111-111111111111','{"filter":"all"}')->'items'->0 ? 'description'),'card description lazy loaded');
select pg_temp.rs_assert((public.rs_page('11111111-1111-1111-1111-111111111111','{"filter":"all"}')->'items'->0->>'contentPartial')::boolean,'partial card marker');

select pg_temp.rs_assert(jsonb_array_length(public.rs_page('11111111-1111-1111-1111-111111111111','{"filter":"watch","cursor":[1003,"https://www.youtube.com/watch?v=test3"]}')->'items')=2,'keyset continuation');
select pg_temp.rs_assert(jsonb_array_length(public.rs_page('22222222-2222-2222-2222-222222222222','{"filter":"all"}')->'items')=0,'owner isolation');
select pg_temp.rs_assert(jsonb_array_length(public.rs_page('11111111-1111-1111-1111-111111111111','{"filter":"all","channel":"alice","tag":"a long tag","terms":["durable","title"]}')->'items')=12,'normalized word/channel/tag search');
select pg_temp.rs_assert(jsonb_array_length(public.rs_page('11111111-1111-1111-1111-111111111111','{"filter":"all","terms":["''); drop table rs_items;--"]}')->'items')=0,'literal injection query');
select pg_temp.rs_assert((public.rs_edit('11111111-1111-1111-1111-111111111111','{"videoUrl":"https://www.youtube.com/watch?v=test1","revision":1,"description":"Cloud description","notes":"Cloud note"}')->>'ok')::boolean,'edit success');
select pg_temp.rs_assert(public.rs_edit('11111111-1111-1111-1111-111111111111','{"videoUrl":"https://www.youtube.com/watch?v=test1","revision":1,"description":"Stale","notes":"Stale"}')->>'code'='document_changed','optimistic edit conflict');
select public.rs_import('11111111-1111-1111-1111-111111111111','{"items":[{"videoUrl":"https://www.youtube.com/watch?v=test1","readerId":"reader1","savedAt":1001,"firstSavedAt":1001,"updatedAt":3000,"title":"new title","author":"Alice","location":"later","tags":[],"status":"saved","checkedAt":2000,"summary":"new summary","summaryCheckedAt":2000,"description":"stale browser description","notes":"stale browser note"}]}');
select pg_temp.rs_assert(public.rs_item('11111111-1111-1111-1111-111111111111','{"videoUrl":"https://www.youtube.com/watch?v=test1"}')->>'description'='Cloud description','import keeps description');
select pg_temp.rs_assert(public.rs_item('11111111-1111-1111-1111-111111111111','{"videoUrl":"https://www.youtube.com/watch?v=test1"}')->>'notes'='Cloud note','import keeps personal notes');
select public.rs_mark('11111111-1111-1111-1111-111111111111','{"videoUrl":"https://www.youtube.com/watch?v=test1","id":"reader1","status":"deleted","now":4000}');
select public.rs_import('11111111-1111-1111-1111-111111111111','{"items":[{"videoUrl":"https://www.youtube.com/watch?v=test1","readerId":"reader1","savedAt":1001,"firstSavedAt":1001,"updatedAt":5000,"title":"stale saved","author":"Alice","location":"later","tags":[],"status":"saved","checkedAt":5000,"summary":"new","summaryCheckedAt":5000}]}');
select pg_temp.rs_assert(public.rs_item('11111111-1111-1111-1111-111111111111','{"videoUrl":"https://www.youtube.com/watch?v=test1"}')->>'status'='deleted','cloud tombstone survives newer migration clock');
select public.rs_import('11111111-1111-1111-1111-111111111111','{"items":[{"videoUrl":"https://www.youtube.com/watch?v=test1","readerId":"replacementReader","savedAt":6000,"firstSavedAt":1001,"updatedAt":6000,"title":"Explicit fresh save","author":"Alice","location":"","tags":[],"status":"saved","checkedAt":0,"summary":null,"summaryCheckedAt":0,"summaryTruncated":false}]}');
select pg_temp.rs_assert(public.rs_item('11111111-1111-1111-1111-111111111111','{"videoUrl":"https://www.youtube.com/watch?v=test1"}')->>'readerId'='replacementReader','explicit new Reader identity restores tombstone');
select pg_temp.rs_assert(public.rs_item('11111111-1111-1111-1111-111111111111','{"videoUrl":"https://www.youtube.com/watch?v=test1"}')->>'summary' is null,'replacement clears stale Reader summary');
select public.rs_verify('11111111-1111-1111-1111-111111111111','{"doc":{"id":"reader2","videoUrl":"https://www.youtube.com/watch?v=test2","title":"Cloud verified","author":"Alice","location":"later","tags":[],"summary":"old identity","summaryTruncated":false},"now":9000}');
select public.rs_import('11111111-1111-1111-1111-111111111111','{"items":[{"videoUrl":"https://www.youtube.com/watch?v=test2","readerId":"newReader2","savedAt":7000,"firstSavedAt":1002,"updatedAt":7000,"title":"Fresh save queued before cloud check","author":"Alice","location":"","tags":[],"status":"saved","checkedAt":0,"summary":null,"summaryCheckedAt":0,"summaryTruncated":false}]}');
select pg_temp.rs_assert(public.rs_item('11111111-1111-1111-1111-111111111111','{"videoUrl":"https://www.youtube.com/watch?v=test2"}')->>'readerId'='newReader2','new identity replaces active row despite later old-identity verification');
select pg_temp.rs_assert(public.rs_verify('11111111-1111-1111-1111-111111111111','{"doc":{"id":"reader2","videoUrl":"https://www.youtube.com/watch?v=test2"},"now":10000}') is null,'old identity verify returns no updated row');
select public.rs_import('11111111-1111-1111-1111-111111111111',jsonb_build_object('items',jsonb_build_array(jsonb_build_object('videoUrl','https://www.youtube.com/watch?v=test3','readerId','reader3','savedAt',1003,'firstSavedAt',1003,'updatedAt',5000,'title','UniqueSummaryBound','author','Alice','location','later','tags','[]'::jsonb,'status','saved','checkedAt',2000,'summary',repeat('漢',64000),'summaryCheckedAt',2000,'summaryTruncated',false))));
select pg_temp.rs_assert(length(public.rs_item('11111111-1111-1111-1111-111111111111','{"videoUrl":"https://www.youtube.com/watch?v=test3"}')->>'summary')=64000,'full summary retained');
select pg_temp.rs_assert(length(public.rs_page('11111111-1111-1111-1111-111111111111','{"filter":"all","terms":["uniquesummarybound"]}')->'items'->0->>'summary')=32768,'display summary bounded');
select pg_temp.rs_assert((public.rs_page('11111111-1111-1111-1111-111111111111','{"filter":"all","terms":["uniquesummarybound"]}')->'items'->0->>'summaryTruncated')::boolean,'display excerpt labelled');
select public.rs_device('11111111-1111-1111-1111-111111111111',jsonb_build_object('action','create','hash',repeat('a',64)));
select pg_temp.rs_assert((public.rs_device('11111111-1111-1111-1111-111111111111',jsonb_build_object('action','get','hash',repeat('a',64)))->>'valid')::boolean,'device exists');
select pg_temp.rs_assert(not (public.rs_device('22222222-2222-2222-2222-222222222222',jsonb_build_object('action','get','hash',repeat('a',64)))->>'valid')::boolean,'device owner restriction');
select public.rs_device('11111111-1111-1111-1111-111111111111','{"action":"revoke"}');
select pg_temp.rs_assert(not (public.rs_device('11111111-1111-1111-1111-111111111111',jsonb_build_object('action','get','hash',repeat('a',64)))->>'valid')::boolean,'device revoke');
select public.rs_ticket('11111111-1111-1111-1111-111111111111',jsonb_build_object('action','create','hash',repeat('b',64),'snapshot','{"id":"reader1"}'::jsonb));
select pg_temp.rs_assert(public.rs_ticket('11111111-1111-1111-1111-111111111111',jsonb_build_object('action','take','hash',repeat('b',64)))->>'id'='reader1','ticket first use');
select pg_temp.rs_assert(public.rs_ticket('11111111-1111-1111-1111-111111111111',jsonb_build_object('action','take','hash',repeat('b',64))) is null,'ticket single use');
select pg_temp.rs_assert((public.rs_rate('11111111-1111-1111-1111-111111111111','{"action":"reserve","needs":{"list":18}}')->>'ok')::boolean,'rate reserve18');
select pg_temp.rs_assert(public.rs_rate('11111111-1111-1111-1111-111111111111','{"action":"reserve","needs":{"list":1}}')->>'source'='local','persisted rate block');
select public.rs_rate('11111111-1111-1111-1111-111111111111',jsonb_build_object('action','block','until',floor(extract(epoch from clock_timestamp())*1000)::bigint+120000));
select pg_temp.rs_assert(public.rs_rate('11111111-1111-1111-1111-111111111111','{"action":"reserve","needs":{"update":1}}')->>'source'='reader','shared reader cooldown');
select pg_temp.rs_assert((public.rs_timer('11111111-1111-1111-1111-111111111111','{"action":"start","id":null,"revision":0,"minutes":15,"newId":"timer-one","now":10000}')->'state'->>'deadline')::bigint=910000,'timer absolute deadline');
select pg_temp.rs_assert(public.rs_timer('11111111-1111-1111-1111-111111111111','{"action":"pause","id":"timer-one","revision":0,"now":20000}')->>'code'='timer_changed','timer stale revision');
select pg_temp.rs_assert(public.rs_timer('11111111-1111-1111-1111-111111111111','{"action":"get","now":910001}')->'state'->>'phase'='expired','timer expiry');
rollback;
